let harness: MongoReplicaSetHarness, server: Server, base = '', token = '';
const actor = new ObjectId(), bytes = Buffer.from('synthetic-video-ingress-body');
let puts = 0, copies = 0;
let hashGate: { entered: () => void; wait: Promise<void> } | null = null;
const objects = new Map<string, { bytes: Buffer; etag: string; versionId: string }>();
const storage: AdminVideoStorage = {
    async put(_id, asset, file) {
        puts++; const body = file.path ? await readFile(file.path) : file.buffer;
        const identity = { etag: `"${asset.id}"`, versionId: asset.id };
        objects.set(asset.key, { bytes: body, ...identity }); return identity;
    },
    async head(_id, asset) { const value = objects.get(asset.key); return value ? { etag: value.etag, versionId: value.versionId } : null; },
    async download(_id, asset, path) { const value = objects.get(asset.key); assert.ok(value); await writeFile(path, value.bytes); },
    async copy() { copies++; throw new Error('No ingress test may publish bytes'); },
    async delete(_id, asset) { objects.delete(asset.key); },
    async readCover() { throw new Error('No ingress test reads a staged cover'); }
};
const headers = () => ({ Authorization: `Bearer ${token}`, 'X-Finitude-Account-Viewer': actor.toHexString() });
async function json(path: string, method = 'GET', body?: unknown) {
    const response = await fetch(base + path, { method, headers: { ...headers(), ...(body === undefined ? {} : { 'Content-Type': 'application/json' }) }, ...(body === undefined ? {} : { body: JSON.stringify(body) }) });
    return { response, body: await response.json() as any };
}
async function create() {
    const result = await json('/video-projects', 'POST', { operationId: randomUUID(), filename: 'source.mp4', byteLength: bytes.length });
    assert.equal(result.response.status, 201); return result.body.item;
}
async function current(id: string) { const result = await json(`/video-projects/${id}`); assert.equal(result.response.status, 200); return result.body.item; }
async function until<T>(read: () => Promise<T>, accept: (value: T) => boolean) {
    const deadline = Date.now() + 5_000;
    for (;;) { const value = await read(); if (accept(value)) return value; if (Date.now() > deadline) throw new Error('Synthetic ingress condition did not settle'); await delay(10); }
}
function fullForm(id: string, operationId: string, revision = 1) {
    const form = new FormData(); form.set('file', new Blob([bytes], { type: 'video/mp4' }), 'source.mp4');
    return fetch(`${base}/video-projects/${id}/source`, { method: 'POST', headers: { ...headers(), 'Idempotency-Key': operationId, 'If-Match': String(revision) }, body: form });
}

/** Sends a valid multipart envelope but holds its file bytes until the test releases the transport. */
function heldBody(id: string, operationId: string, kind: 'source' | 'covers' = 'source', revision = 1) {
    const boundary = `archtree-${randomUUID()}`;
    const prefix = Buffer.from(`--${boundary}\r\nContent-Disposition: form-data; name="file"; filename="${kind === 'source' ? 'source.mp4' : 'cover.jpg'}"\r\nContent-Type: ${kind === 'source' ? 'video/mp4' : 'image/jpeg'}\r\n\r\n`);
    const suffix = Buffer.from(`\r\n--${boundary}--\r\n`);
    let request: ReturnType<typeof httpRequest>;
    const result = new Promise<{ status: number; body: any }>((resolve, reject) => {
        request = httpRequest(`${base}/video-projects/${id}/${kind}`, { method: 'POST', headers: { ...headers(), 'Idempotency-Key': operationId, 'If-Match': String(revision),
            'Content-Type': `multipart/form-data; boundary=${boundary}`, 'Content-Length': prefix.length + bytes.length + suffix.length } }, response => {
            const chunks: Buffer[] = []; response.on('data', part => chunks.push(part)); response.on('end', () => {
                const value = Buffer.concat(chunks).toString(); resolve({ status: response.statusCode!, body: value ? JSON.parse(value) : null });
            });
        });
        request.on('error', error => { if (request.destroyed) resolve({ status: 0, body: null }); else reject(error); });
        request.write(prefix);
    });
    return { result, end: () => request!.end(Buffer.concat([bytes, suffix])), abort: () => request!.destroy() };
}

