test('held multipart is visible after reload and reconciles pending; concurrent same or different intent is rejected before bytes', async () => {
    const project = await create(), operationId = randomUUID(), body = heldBody(project.id, operationId);
    try {
        const reload = await until(() => current(project.id), value => value.ingress.source?.state === 'receiving');
        assert.equal(reload.source.operationId, operationId); assert.equal(reload.source.status, 'pending'); assert.equal(reload.revision, project.revision);
        assert.deepEqual(reload.ingress.source, { operationId, expectedRevision: 1, state: 'receiving', issue: null });
        const recovered = await json(`/video-projects/${project.id}/source/reconcile`, 'POST', { operationId });
        assert.equal(recovered.response.status, 200); assert.equal(recovered.body.item.source.status, 'pending'); assert.equal(recovered.body.receipt.operationId, operationId);
        assert.equal(puts, 0); assert.equal((await videoProjects().findOne({ _id: new ObjectId(project.id) }))?.assets.length, 0);
        for (const other of [operationId, randomUUID()]) {
            const response = await fetch(`${base}/video-projects/${project.id}/source`, { method: 'POST', headers: { ...headers(), 'Idempotency-Key': other, 'If-Match': '1', 'Content-Type': 'multipart/form-data; boundary=broken' }, body: 'not multipart' });
            assert.equal(response.status, 409); assert.equal((await response.json() as any).code, 'ADMIN_VIDEO_INGRESS_BUSY');
        }
        body.end(); const result = await body.result;
        assert.equal(result.status, 200); assert.equal(result.body.item.source.status, 'ready'); assert.equal(result.body.item.ingress.source.state, 'admitted'); assert.equal(puts, 1);
        assert.ok(!JSON.stringify(result.body).includes('requestId')); assert.ok(!JSON.stringify(result.body).includes('leaseUntil'));
    } finally { body.abort(); await body.result; }
});

test('a held digest remains pending and metadata saves do not invalidate its pre-admitted upload intent', async () => {
    const project = await create(), operationId = randomUUID(); let entered!: () => void, release!: () => void;
    const started = new Promise<void>(resolve => { entered = resolve; }), wait = new Promise<void>(resolve => { release = resolve; });
    hashGate = { entered, wait }; const upload = fullForm(project.id, operationId);
    try {
        await started;
        const reload = await current(project.id); assert.equal(reload.source.status, 'pending'); assert.equal(puts, 0);
        const reconciled = await json(`/video-projects/${project.id}/source/reconcile`, 'POST', { operationId });
        assert.equal(reconciled.response.status, 200); assert.equal(reconciled.body.item.ingress.source.state, 'receiving');
        const edited = await json(`/video-projects/${project.id}`, 'PATCH', { operationId: randomUUID(), expectedRevision: 1, patch: { title: 'Saved while hashing' } }); assert.equal(edited.response.status, 200);
        release(); const result = await upload; assert.equal(result.status, 200);
        const finished = await result.json() as any; assert.equal(finished.item.draft.title, 'Saved while hashing'); assert.equal(finished.item.source.status, 'ready'); assert.equal(puts, 1);
    } finally { release(); await upload; hashGate = null; }
});

test('aborted ingress settles as not admitted without S3 bytes and permits the exact original retry', async () => {
    const project = await create(), operationId = randomUUID(), body = heldBody(project.id, operationId);
    await until(() => current(project.id), value => value.ingress.source?.state === 'receiving');
    body.abort(); await body.result;
    const failed = await until(() => current(project.id), value => value.ingress.source?.state === 'failed');
    assert.equal(failed.source.status, 'failed'); assert.equal(puts, 0); assert.equal(objects.size, 0);
    const reconciled = await json(`/video-projects/${project.id}/source/reconcile`, 'POST', { operationId });
    assert.equal(reconciled.response.status, 200); assert.equal(reconciled.body.item.source.status, 'failed');
    const retry = await fullForm(project.id, operationId); assert.equal(retry.status, 200); assert.equal(puts, 1);
});

test('expiration fences a late digest before asset admission or S3 dispatch', async () => {
    const project = await create(), operationId = randomUUID(); let entered!: () => void, release!: () => void;
    const started = new Promise<void>(resolve => { entered = resolve; }), wait = new Promise<void>(resolve => { release = resolve; });
    hashGate = { entered, wait }; const upload = fullForm(project.id, operationId);
    try {
        await started;
        await videoProjects().updateOne({ _id: new ObjectId(project.id) }, { $set: { 'ingresses.0.leaseUntil': new Date(0) } });
        const result = await json(`/video-projects/${project.id}/source/reconcile`, 'POST', { operationId }); assert.equal(result.body.item.ingress.source.state, 'failed');
        const collision = await json(`/video-projects/${project.id}`, 'PATCH', { operationId, expectedRevision: 1, patch: { title: 'Reused upload intent' } });
        assert.equal(collision.response.status, 409); assert.equal(collision.body.code, 'ADMIN_VIDEO_OPERATION_CONFLICT');
        release(); const late = await upload; assert.equal(late.status, 409); assert.equal((await late.json() as any).code, 'ADMIN_VIDEO_INGRESS_EXPIRED');
        assert.equal(puts, 0); assert.equal((await videoProjects().findOne({ _id: new ObjectId(project.id) }))?.assets.length, 0);
    } finally { release(); await upload; hashGate = null; }
});

test('cancellation retains receiving evidence until request work ends, before cleanup and account deletion', async () => {
    const project = await create(), operationId = randomUUID(), body = heldBody(project.id, operationId);
    await until(() => current(project.id), value => value.ingress.source?.state === 'receiving');
    const cancel = await json(`/video-projects/${project.id}/cancel`, 'POST', { operationId: randomUUID(), expectedRevision: 1 }); assert.equal(cancel.response.status, 202);
    await runAdminVideoWorkerOnce({ storage }); assert.equal((await videoProjects().findOne({ _id: new ObjectId(project.id) }))?.cleanupComplete, false);
    assert.deepEqual(await deleteListenerAccountData(actor.toHexString()), { status: 'sharedProvenance' });
    body.abort(); await body.result;
    await until(() => current(project.id), value => value.ingress.source?.state === 'failed');
    await runAdminVideoWorkerOnce({ storage }); assert.equal((await videoProjects().findOne({ _id: new ObjectId(project.id) }))?.cleanupComplete, true);
    assert.equal(puts, 0); assert.equal(copies, 0);
});

test('a receiving cover fences an already displayed approval and parallel frame extraction', async () => {
    const project = await create(), upload = await fullForm(project.id, randomUUID()); assert.equal(upload.status, 200);
    await runAdminVideoWorkerOnce({ storage, process: async ({ inputPath }) => ({ plan: 'direct', outputPath: inputPath, contentType: 'video/mp4', byteLength: bytes.length,
        durationSeconds: 20, width: 1920, height: 1080, videoCodec: 'hevc', audioCodec: 'aac' }) });
    const ready = await current(project.id), operationId = randomUUID(), body = heldBody(project.id, operationId, 'covers', ready.revision);
    try {
        const waiting = await until(() => current(project.id), value => value.ingress.cover?.state === 'receiving'); assert.equal(waiting.approvalDigest, null);
        const recovery = await json(`/video-projects/${project.id}/covers/reconcile`, 'POST', { operationId }); assert.equal(recovery.response.status, 200); assert.equal(recovery.body.item.ingress.cover.state, 'receiving');
        const publish = await json(`/video-projects/${project.id}/publish`, 'POST', { operationId: randomUUID(), expectedRevision: ready.revision, approvalDigest: ready.approvalDigest }); assert.equal(publish.response.status, 409);
        const frame = await json(`/video-projects/${project.id}/cover-frame`, 'POST', { operationId: randomUUID(), expectedRevision: ready.revision, timeSeconds: 1 }); assert.equal(frame.response.status, 409);
        assert.equal(copies, 0); assert.equal(await getDb()!.collection('audioTracks').countDocuments(), 0);
    } finally { body.abort(); await body.result; }
});

test('a newer cover ingress fences selection by a frame worker that was already running', async () => {
    const project = await create(), upload = await fullForm(project.id, randomUUID()); assert.equal(upload.status, 200);
    await runAdminVideoWorkerOnce({ storage, process: async ({ inputPath }) => ({ plan: 'direct', outputPath: inputPath, contentType: 'video/mp4', byteLength: bytes.length,
        durationSeconds: 20, width: 1920, height: 1080, videoCodec: 'hevc', audioCodec: 'aac' }) });
    const ready = await current(project.id);
    await json(`/video-projects/${project.id}/cover-frame`, 'POST', { operationId: randomUUID(), expectedRevision: ready.revision, timeSeconds: 1 });
    let entered!: () => void, release!: () => void;
    const started = new Promise<void>(resolve => { entered = resolve; }), wait = new Promise<void>(resolve => { release = resolve; });
    const frame = runAdminVideoWorkerOnce({ storage, frame: async input => {
        entered(); await wait;
        const path = `${input.workDirectory}/frame.jpg`;
        await sharp({ create: { width: 8, height: 8, channels: 3, background: '#776655' } }).jpeg().toFile(path);
        return { path, contentType: 'image/jpeg' };
    } });
    await started; const pending = await current(project.id), body = heldBody(project.id, randomUUID(), 'covers', pending.revision);
    try {
        await until(() => current(project.id), value => value.ingress.cover?.state === 'receiving');
        release(); await frame;
        const result = await current(project.id); assert.equal(result.frame.state, 'ready'); assert.equal(result.covers.length, 1);
        assert.equal(result.selectedCoverId, null); assert.equal(result.draft.coverChoice, 'automatic');
    } finally { release(); await frame; body.abort(); await body.result; }
});

test('ingress history is bounded before multipart decoding', async () => {
    const project = await create();
    await videoProjects().updateOne({ _id: new ObjectId(project.id) }, { $set: { ingresses: Array.from({ length: 256 }, () => ({
        operationId: randomUUID(), kind: 'source' as const, expectedRevision: 1, state: 'failed' as const, requestId: null,
        leaseUntil: new Date(0), completedAt: new Date(0), issue: 'upload_not_admitted', coverSelectionRevision: 0, assetId: null
    })) } });
    const response = await fetch(`${base}/video-projects/${project.id}/source`, { method: 'POST', headers: { ...headers(), 'Idempotency-Key': randomUUID(), 'If-Match': '1', 'Content-Type': 'multipart/form-data; boundary=broken' }, body: 'not multipart' });
    assert.equal(response.status, 409); assert.equal((await response.json() as any).code, 'ADMIN_VIDEO_OPERATION_LIMIT');
    assert.equal(puts, 0); assert.equal((await videoProjects().findOne({ _id: new ObjectId(project.id) }))?.ingresses.length, 256);
});
